<?php namespace App\Filament\Resources;use App\Filament\Resources\UpbringingAppealResource\Pages;use App\Models\UpbringingAppeal;use Illuminate\Support\Facades\DB;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;class UpbringingAppealResource extends Resource{protected static ?string $model=UpbringingAppeal::class;protected static ?string $navigationGroup='Воспитательная работа';protected static ?string $navigationLabel='Обращения';protected static ?string $pluralModelLabel='Обращения';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('source_type')->label('Источник')->options(['student'=>'Студент','parent'=>'Родитель','employee'=>'Сотрудник','other'=>'Другое'])->required(),Forms\Components\TextInput::make('contact_name')->label('ФИО/контакт'),Forms\Components\TextInput::make('contact')->label('Телефон / e-mail'),Forms\Components\TextInput::make('category')->label('Категория')->required(),Forms\Components\Textarea::make('message')->label('Обращение')->required()->columnSpan('full'),Forms\Components\Select::make('status')->label('Статус')->options(['new'=>'Новое','in_progress'=>'В работе','resolved'=>'Решено'])->required(),Forms\Components\Textarea::make('resolution')->label('Решение')->columnSpan('full')])->columns(2);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('created_at')->label('Дата')->dateTime('d.m.Y H:i'),Tables\Columns\TextColumn::make('contact_name')->label('Заявитель')->searchable(),Tables\Columns\TextColumn::make('category')->label('Категория'),Tables\Columns\BadgeColumn::make('status')->label('Статус'),Tables\Columns\TextColumn::make('message')->label('Обращение')->limit(60)])->actions([Tables\Actions\EditAction::make()->label('Изменить')]);}public static function getPages():array{return['index'=>Pages\ListUpbringingAppeals::route('/'),'create'=>Pages\CreateUpbringingAppeal::route('/